'use strict';
let draft={institution:'',title:'',background:'',source:'',scope:'private',confirmed:false,files:[]},draftStep=1;
const draftPreviews=new Map();
function bytesLabel(n){return n<1048576?(n/1024).toFixed(0)+' KB':(n/1048576).toFixed(1)+' MB'}
function previewFile(f){if(!draftPreviews.has(f.id))draftPreviews.set(f.id,URL.createObjectURL(f.blob));return draftPreviews.get(f.id)}
function fileRows(){return draft.files.map((f,n)=>`<li class="file-row">${f.type.startsWith('image/')?imageHTML(previewFile(f),'所选图片的本机预览'):f.type.startsWith('video/')?`<video src="${previewFile(f)}" preload="metadata" muted playsinline aria-label="所选视频预览"></video>`:'<span class="file-icon">'+icon('file-text')+'</span>'}<div><strong>${esc(f.name)}</strong><p class="muted">${n+1} · ${bytesLabel(f.size)} · ${f.type.startsWith('video/')?'视频':'图片'}</p></div><div class="file-controls"><button class="quiet" data-move="${f.id}" data-direction="-1" ${n===0?'disabled':''} aria-label="上移 ${esc(f.name)}">上移</button><button class="quiet" data-move="${f.id}" data-direction="1" ${n===draft.files.length-1?'disabled':''} aria-label="下移 ${esc(f.name)}">下移</button><button class="quiet" data-remove="${f.id}" aria-label="移出 ${esc(f.name)}">移出</button></div></li>`).join('')}
function renderProvide(){const steps=['整理资料','补充说明','确认范围'];return `<div class="content-column">${backLink('participate','参与')}<h1>${['先整理你想提供的资料','补充一点背景说明','想一想哪些内容可以公开'][draftStep-1]}</h1><p class="muted">${['只选一份也可以，其他说明可以稍后补充。','不用一次写完。不确定的地方可以如实注明。','这些选择只记录意愿，还不代表已经审核或发布。'][draftStep-1]}</p><ol class="steps" aria-label="资料整理步骤">${steps.map((s,n)=>`<li class="${draftStep===n+1?'current':''}" ${draftStep===n+1?'aria-current="step"':''}><span>${n+1}</span>${s}</li>`).join('')}</ol>${draftStep===1?`<label class="form-field"><span>关联机构（可稍后选择）</span><input id="draft-institution" type="text" maxlength="150" value="${esc(getInstitution(draft.institution)?.name?getInstitution(draft.institution).name+' ['+draft.institution+']':draft.institution)}" placeholder="输入机构名称或资料编号" list="draft-institution-options"><datalist id="draft-institution-options">${institutions.slice(0,30).map(i=>`<option value="${esc(i.name)} [${i.id}]"></option>`).join('')}</datalist></label><div class="file-picker"><label class="button primary" for="draft-files">${icon('folder-open')}从相册或文件选择</label><input class="visually-hidden" id="draft-files" type="file" accept="image/*,video/*" multiple><div class="capture-actions"><label for="capture-photo">${icon('camera')}拍照</label><input class="visually-hidden" id="capture-photo" type="file" accept="image/*" capture="environment"><label for="capture-video">${icon('video')}录像</label><input class="visually-hidden" id="capture-video" type="file" accept="video/*" capture="environment"></div><p class="muted">选入时只在本机；主动保存服务器草稿或提交时才上传。支持图片10MB、视频50MB，每份6个/100MB。</p></div><div class="heading-line spaced"><h2>已选资料</h2><span class="muted">${draft.files.length} 份 · ${bytesLabel(draft.files.reduce((n,f)=>n+f.size,0))}</span></div><ol class="file-list">${fileRows()||'<li class="empty muted">还没有选入资料，先选一份试试看。</li>'}</ol><div class="draft-storage"><a class="button quiet" href="#access">离线整理与导入备用办法</a><button class="quiet" id="restore-draft">${icon('history')}恢复这台设备保存的草稿</button><p id="draft-storage-status" class="muted" role="status">未保存的内容仅在本次打开期间保留。</p></div>`:draftStep===2?`<label class="form-field"><span>资料标题</span><input id="draft-title" type="text" maxlength="150" value="${esc(draft.title)}" placeholder="怎样称呼这一组资料？"></label><label class="form-field"><span>发生或取得资料的背景</span><textarea id="draft-background" maxlength="20000" placeholder="时间、地点、记得的事情，以及不能确认的部分。">${esc(draft.background)}</textarea></label><label class="form-field"><span>来源说明（选填）</span><input id="draft-source" type="text" maxlength="2000" value="${esc(draft.source)}" placeholder="自己保存、公开页面，或其他取得方式"></label><p class="notice">这些说明会放入你的私人草稿。不要把别人的私人联系方式当作公开材料。</p>`:`<fieldset class="scope-options"><legend>这一组资料的初步意愿</legend><label><input type="radio" name="draft-scope" value="private" ${draft.scope==='private'?'checked':''}><span><strong>先保留给自己</strong><small>只整理和保存，不准备公开。</small></span></label><label><input type="radio" name="draft-scope" value="review" ${draft.scope==='review'?'checked':''}><span><strong>希望先私下核对</strong><small>主动提交后供私人核对，不自动公开。</small></span></label><label><input type="radio" name="draft-scope" value="public" ${draft.scope==='public'?'checked':''}><span><strong>考虑提供公开版本</strong><small>原件仍不自动公开，逐份确认适合公开的内容。</small></span></label></fieldset>${draft.scope==='public'?`<h2 class="section-head">逐份标记公开意愿</h2><div class="scope-files">${draft.files.map(f=>`<label><input type="checkbox" data-file-scope="${f.id}" ${f.publicIntent?'checked':''}><span>${esc(f.name)}<small>希望在处理并核对后公开</small></span></label><label><input type="checkbox" data-file-export="${f.id}" ${f.exportIntent?'checked':''}><span>允许 ${esc(f.name)} 随公开包复制传播<small>只在该文件另获准公开后有效</small></span></label>`).join('')||'<p class="muted">尚未选择文件。</p>'}</div><label class="check-line"><input id="draft-confirmed" type="checkbox" ${draft.confirmed?'checked':''}><span>我理解需要确认授权，并检查文件中的个人信息；公开文件须先处理个人信息；主动提交后仍需核对，不会自动发布。</span></label>`:''}<p class="notice">此页没有自动遮挡姓名、脸部或位置，也没有身份认证。实际公开前需要另外准备脱敏副本、确认授权并审核。</p>`}<div class="soft-note"><h3 class="icon-heading">${icon('lock-keyhole')}先保存草稿，再决定下一步</h3><p>浏览器保存可能被系统清理。重要原件应另外留一份；导出的草稿包包含原件，仅供你自己保存。</p></div><div class="draft-actions"><button data-save-draft>${icon('save')}保存本机草稿</button>${draftStep>1?'<button data-prev-step>上一步</button>':''}<button class="primary" ${draftStep<3?'data-next-step':'data-export-draft'}>${draftStep<3?'':icon('download')}${draftStep<3?'下一步':'导出私人草稿包'}</button></div><p id="draft-result" class="muted" role="status"></p>${draftStep===3?intakeSubmissionPanel():''}</div>`}
function refreshDraft(){const y=window.scrollY;$('main').innerHTML=renderProvide();window.scrollTo(0,y)}
function openDraftDB(){return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(Error('此浏览器不支持本机草稿保存'));const r=indexedDB.open('kanjian-local-drafts-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('drafts');r.onerror=()=>reject(r.error);r.onsuccess=()=>resolve(r.result)})}
async function saveDraft(){let db;try{db=await openDraftDB();await new Promise((resolve,reject)=>{const t=db.transaction('drafts','readwrite');t.objectStore('drafts').put({...draft,savedAt:new Date().toISOString()},'current');t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error||Error('保存中断'))});notify('已保存到这台设备的浏览器，没有上传。');if($('draft-result'))$('draft-result').textContent='本机草稿已保存。还可以导出一份私人备份。'}catch{notify('本机保存未成功，已选资料仍在当前页面。请导出私人草稿包另存。')}finally{db?.close()}}
async function restoreDraft(){let db;try{db=await openDraftDB();const data=await new Promise((resolve,reject)=>{const r=db.transaction('drafts').objectStore('drafts').get('current');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});if(!data)return notify('这台设备还没有保存的草稿。');draft=data;draftStep=1;for(const u of draftPreviews.values())URL.revokeObjectURL(u);draftPreviews.clear();refreshDraft();notify('已恢复这台设备的草稿和原文件。')}catch{notify('没有成功读取本机草稿。你也可以重新选择原文件。')}finally{db?.close()}}
async function addFiles(fileList){let added=0;for(const file of fileList){if(!/^(image|video)\//.test(file.type)){notify('只接受浏览器识别的图片或视频；不支持的文件没有选入。');continue}draft.files.push({id:crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random(),name:file.name,size:file.size,type:file.type,blob:file,publicIntent:false});added++}refreshDraft();if(added)notify('已选入 '+added+' 份资料，只在本机整理。')}
function draftManifest(){return {format:'kanjian-private-draft-v1',isSubmission:false,isPublic:false,created:new Date().toISOString(),institution:draft.institution,title:draft.title,background:draft.background,source:draft.source,scopeIntent:draft.scope,scopeConfirmed:draft.confirmed,files:draft.files.map((f,n)=>({order:n+1,id:f.id,name:f.name,size:f.size,type:f.type,publicIntent:!!f.publicIntent}))}}
async function exportDraft(){const total=draft.files.reduce((n,f)=>n+f.size,0);if(total>200*1048576){saveBlob('私人草稿-说明与文件清单.json',new Blob([JSON.stringify(draftManifest(),null,2)],{type:'application/json'}));notify('原件超过 200 MB，已导出说明与清单；原文件请另存并使用分包工具。');$('draft-result').textContent='大文件原件没有装入这个清单。请另外保存所选原件。';return}try{const files=[{name:'私人草稿-请勿公开.txt',bytes:new TextEncoder().encode('本包包含私人原件，仅供本人保存。没有提交、审核或公开。请勿把这个草稿包当作公开资料包传播。\n'+draft.title)},{name:'draft.json',bytes:new TextEncoder().encode(JSON.stringify(draftManifest(),null,2))}];for(let n=0;n<draft.files.length;n++){const f=draft.files[n],safe=f.name.replace(/[\\/\x00-\x1f]/g,'_');files.push({name:'原件/'+String(n+1).padStart(3,'0')+'-'+safe,bytes:new Uint8Array(await f.blob.arrayBuffer())})}saveBlob('看见-私人草稿-请勿公开.zip',zipFiles(files));notify('已请求保存私人草稿包，包含原件，没有提交。')}catch{notify('草稿包没有成功生成。请先保存本机草稿，原文件另外保留。')}}
document.addEventListener('input',e=>{if(e.target.id==='draft-institution'){const value=e.target.value,m=value.match(/\[(INST-\d{4})\]$/);draft.institution=m?m[1]:value;const matches=institutions.filter(i=>(i.name+' '+i.alias+' '+i.id).includes(value)).slice(0,30);if($('draft-institution-options'))$('draft-institution-options').innerHTML=matches.map(i=>`<option value="${esc(i.name)} [${i.id}]"></option>`).join('');}const keys={'draft-title':'title','draft-background':'background','draft-source':'source'};if(keys[e.target.id])draft[keys[e.target.id]]=e.target.value});
document.addEventListener('change',e=>{if(['draft-files','capture-photo','capture-video'].includes(e.target.id))addFiles(e.target.files);if(e.target.name==='draft-scope'){draft.scope=e.target.value;refreshDraft()}if(e.target.dataset.fileScope){const f=draft.files.find(f=>f.id===e.target.dataset.fileScope);if(f)f.publicIntent=e.target.checked}if(e.target.id==='draft-confirmed')draft.confirmed=e.target.checked;if(e.target.dataset.fileExport){const f=draft.files.find(f=>f.id===e.target.dataset.fileExport);if(f)f.exportIntent=e.target.checked}});
document.addEventListener('click',e=>{const move=e.target.closest('[data-move]');if(move){const n=draft.files.findIndex(f=>f.id===move.dataset.move),to=n+Number(move.dataset.direction);if(n>=0&&to>=0&&to<draft.files.length){[draft.files[n],draft.files[to]]=[draft.files[to],draft.files[n]];refreshDraft()}}const remove=e.target.closest('[data-remove]');if(remove){const id=remove.dataset.remove;draft.files=draft.files.filter(f=>f.id!==id);if(draftPreviews.has(id)){URL.revokeObjectURL(draftPreviews.get(id));draftPreviews.delete(id)}refreshDraft();notify('已从本次草稿移出，设备上的原文件没有删除。')}if(e.target.closest('[data-save-draft]'))saveDraft();if(e.target.closest('#restore-draft'))restoreDraft();if(e.target.closest('[data-next-step]')){draftStep=Math.min(3,draftStep+1);$('main').innerHTML=renderProvide();window.scrollTo(0,0)}if(e.target.closest('[data-prev-step]')){draftStep=Math.max(1,draftStep-1);$('main').innerHTML=renderProvide();window.scrollTo(0,0)}if(e.target.closest('[data-export-draft]'))exportDraft()});
